INSERT INTO countries(id,name,code,iso3,iso_numeric,dialing_code,default_currency,nationality,continent,alias,description,owner_id,created_by,updated_by)
SELECT seed.id,seed.name,seed.code,seed.iso3,seed.iso_numeric,seed.dialing_code,seed.default_currency,seed.nationality,seed.continent,seed.alias,seed.description,actor.id,actor.id,actor.id
FROM seed CROSS JOIN actor
ON CONFLICT DO NOTHING;

WITH actor AS (
 SELECT id FROM users
 WHERE system_role='super_admin' AND status='approved' AND email_verified=true
 ORDER BY created_at,id LIMIT 1
)
INSERT INTO country_events(country_id,actor_id,action,changes)
SELECT c.id,actor.id,'Created',jsonb_build_object('seeded',jsonb_build_object('before',NULL,'after',true))
FROM countries c CROSS JOIN actor
WHERE NOT EXISTS (SELECT 1 FROM country_events e WHERE e.country_id=c.id AND e.action='Created');

DO $runtime_access$
BEGIN
 IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='saicrm_runtime') THEN
  GRANT SELECT, INSERT, UPDATE, DELETE ON countries, country_business_lines TO saicrm_runtime;
  GRANT SELECT, INSERT ON country_events TO saicrm_runtime;
  GRANT USAGE, SELECT ON SEQUENCE countries_sequence_no_seq, country_events_id_seq TO saicrm_runtime;
 END IF;
END $runtime_access$;

INSERT INTO schema_migrations(version) VALUES(8) ON CONFLICT DO NOTHING;
COMMIT;
